Section WithRIP.
Hypothesis RIP : rip_stmt.

Definition string_read_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (f d src : Z) (st : sfst) (j : nat) (kb dj : list byte) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (m' : mem),
    let len' := Z.min (Z.of_nat j) 1 in
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 len') a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(f, f + 232); (d, d + 1); (bv_unsigned sp - STRING_READ_DEPTH, bv_unsigned sp)] m m'
    /\ wmono asegs m m' /\ mem_inv asegs m' /\ stk asegs m' lo (bv_unsigned sp)
    /\ rw_cells asegs m' f (sfile (mkSF (src + len') (src + Z.of_nat j) (sf_wend st) (sf_wpos st) (sf_wbase st) (sf_read st) (sf_buf st)
                                    (sf_bsz st) (sf_mode st) (sf_lock st) (src + Z.of_nat j) (sf_shend st) (sf_shlim st) (sf_shcnt st)))
    /\ rw_cells asegs m' d [CB 1%nat (firstn (Z.to_nat len') kb ++ skipn (Z.to_nat len') dj)]
    /\ bytes_at asegs m' src kb.

Theorem string_read_spec : forall ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (f d src : Z) (st : sfst) (j : nat) (kb dj : list byte) (lo : Z),
  a0 = Z_to_bv 64 f -> a1 = Z_to_bv 64 d -> a2 = Z_to_bv 64 1 ->
  rw_cells asegs m f (sfile st) -> sf_ok st -> sf_cookie st = src -> bv_unsigned sp + 64 <= f -> f + 232 <= 2^47 ->
  rw_cells asegs m d [CB 1%nat dj] -> bv_unsigned sp <= d -> d + 1 <= bv_unsigned sp + 64 ->
  bytes_at asegs m src kb -> find_byte 0 (firstn (Z.to_nat 257) kb) = Some j -> (j < 8)%nat -> memchr_ok src 0 257 kb -> 0 < src ->
  src + Z.of_nat (length kb) <= lo ->
  chk_ok m src (Z.of_nat j + 1) -> chk_ok m d 1 -> m2s_cells m -> icells_mc m -> icells m ->
  stk asegs m lo (bv_unsigned sp) -> lo <= bv_unsigned sp - STRING_READ_DEPTH -> kHighShadowEnd + 8 <= lo -> bv_unsigned sp + 64 <= 2^47 ->
  mem_inv asegs m ->
  evt asegs (string_read_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc f d src st j kb dj lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
